import React, { useEffect, useRef, useState } from 'react';
import { ArrowDownToLine, ArrowLeft, ArrowRight, ArrowUpRight, Bell, BookMarked, BookOpen, Check, CheckCheck, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Clapperboard, Clock3, Copy, Download, Ellipsis, Feather, FileText, FolderOpen, GraduationCap, Heart, LayoutDashboard, Lightbulb, ListTree, LoaderCircle, Menu, MessageCircle, MessagesSquare, MoreHorizontal, PanelLeftClose, PanelRightClose, Play, Plus, RefreshCw, ScanText, Search, Send, Settings2, Sparkles, Star, Type, Upload, UsersRound, WandSparkles, Workflow, X, Zap, Crown, CheckCircle2, Maximize2 } from 'lucide-react';
import {videoEnabled} from './features';
import { Brand, BookCover } from './Art';
import { ReferenceHome, ReferenceTools, QuickStartDialog } from './Workbench';
import { NovelDesk, DismantleDesk, DraftReviewDialog } from './ProductDesk';
import { applyDraft } from './research';
import { readStoredArray, writeStoredValue } from './storage';
import { placeRecentlyEdited, splitManuscript, saveChapterVersion } from './works';
import { GenerationProvider, GenerationStatus, useGeneration } from './Generation';
import { SettingsDialog } from './Settings';
import { WorkDetailsDialog, ChapterManager, VersionDialog } from './WorkManagement';
import { VideoStudio, SubmissionDesk } from './StudioPages';
import { AccountProvider,AccountAccess,useAccount } from './Account';
import { WorkspaceProvider,WorkspaceStatus,useCollection,useWorkspace } from './Workspace.jsx';
import { GenerationHistory } from './GenerationHistory';
import { ChapterPlanner } from './ChapterPlanner';
import { validateWork } from './backup';
import { initialWorks, tools, workflows, wordCount, workWords } from './data';
import './studio.css';
import { WorkCard, WorksPage } from './Library';
import { AccountBilling, BillingBadge, BillingProvider, MembershipPage, TaskMeter, useBilling, useTaskMeter } from './Billing.jsx';

const iconMap = { BookOpen, Feather, Clapperboard, ScanText, Lightbulb, ListTree, UsersRound, WandSparkles, MessagesSquare, Type };
const navItems = [
 { id:'home', label:'创作工作台', icon:LayoutDashboard },
 { id:'works', label:'我的作品', icon:FolderOpen },
  { id:'novels', label:'小说写作', icon:BookOpen, section:'创作功能', nested:true },
 { id:'scripts', label:'剧本创作', icon:Clapperboard, nested:true },
 ...(videoEnabled?[{ id:'video', label:'漫剧工坊', icon:Play, nested:true }]:[]),
 { id:'dismantle', label:'小说拆书', icon:BookMarked, nested:true },
 { id:'tools', label:'AI 工具广场', icon:Sparkles, section:'AI 工具', nested:true, badge:'精选' },
 { id:'workflows', label:'创作工作流', icon:Workflow, nested:true },
 { id:'history',label:'生成记录',icon:Clock3,section:'创作记录' },
 { id:'submit', label:'投稿中心', icon:Send, section:'创作服务' },
 { id:'learn', label:'写作课堂', icon:GraduationCap },
 { id:'membership', label:'会员与墨点', icon:Crown }
];
function useStored(key,fallback){return useCollection(key.replace(/^mdd-|-v1$/g,''),fallback);}
const uid = () => `${Date.now().toString(36)}${Math.random().toString(36).slice(2,6)}`;
const cn = (...classes) => classes.filter(Boolean).join(' ');
function Icon({ name, ...props }) { const Component = iconMap[name] || Sparkles; return <Component {...props}/>; }
function Empty({ title, text, action }) { return <div className="empty-state"><Feather size={36}/><h3>{title}</h3><p>{text}</p>{action}</div>; }

export function App() { return <AccountProvider><WorkspaceProvider><GenerationProvider><BillingProvider><WritingApp/></BillingProvider></GenerationProvider></WorkspaceProvider></AccountProvider>; }

export function WritingApp() {
 const billing=useBilling();
 const [route, setRoute] = useState(location.hash.slice(1) || 'home');
 const [allWorks, setWorks, workSaveError] = useStored('mdd-works-v1', initialWorks);
 const works=allWorks.filter(work=>!work.deletedAt);
 const trashWorks=allWorks.filter(work=>work.deletedAt);
 const [favorites, setFavorites] = useStored('mdd-favorites-v1', ['ideas', 'polish']);
 const [submissions, setSubmissions] = useStored('mdd-submissions-v1', []);
 const [modal, setModal] = useState(null);const [videoHandoff,setVideoHandoff]=useState(null),[submissionWorkId,setSubmissionWorkId]=useState('');const [workspaceRevision,setWorkspaceRevision]=useState(0);
 useEffect(()=>setModal(null),[billing.navigationKey]);
 const [toast, setToast] = useState('');
 const [search, setSearch] = useState('');
 const [mobileNav, setMobileNav] = useState(false);
 const toastTimer = useRef();
 const importRef = useRef();
 const notify = message => { setToast(message); clearTimeout(toastTimer.current); toastTimer.current = setTimeout(() => setToast(''), 3200); };
 const navigate = id => {if(id!=='video')setVideoHandoff(null);if(id!=='submit')setSubmissionWorkId(''); location.hash = id; setRoute(id); setMobileNav(false); window.scrollTo(0,0); };
 useEffect(() => { const change = () => { setRoute(location.hash.slice(1) || 'home'); setModal(null); window.scrollTo(0,0); }; window.addEventListener('hashchange',change); return () => window.removeEventListener('hashchange',change); }, []);
 useEffect(() => { const onKey = event => { if ((event.metaKey || event.ctrlKey) && event.key === 'k') { event.preventDefault(); setModal({ type:'search' }); } if (event.key === 'Escape') { setModal(null); setMobileNav(false); } }; window.addEventListener('keydown',onKey); return () => window.removeEventListener('keydown',onKey); }, []);
 useEffect(() => {
  if(!modal) return;
  const dialog=document.querySelector('.modal');
  if(!dialog) return;
  const previous=document.activeElement;
  const elements=()=>Array.from(dialog.querySelectorAll('button:not([disabled]),input:not([disabled]),textarea:not([disabled]),select:not([disabled]),[tabindex="0"]')).filter(element=>element.offsetParent!==null);
  const initial=dialog.querySelector('input:not([disabled]),textarea:not([disabled]),select:not([disabled])')||elements()[0];
  const frame=requestAnimationFrame(()=>initial?.focus());
  const trap=event=>{if(event.key!=='Tab')return;const candidates=elements();if(!candidates.length)return;const first=candidates[0],last=candidates.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}};
  dialog.addEventListener('keydown',trap);
  return()=>{cancelAnimationFrame(frame);dialog.removeEventListener('keydown',trap);if(previous?.isConnected)previous.focus();};
 },[modal?.type]);
 const createWork = ({ title, kind, genre, idea = '', outline, characters = '', text = '' }) => {
  const id = uid();
  const work = { id, title, kind, genre, cover: genre === '言情' ? 'spring' : genre === '科幻' ? 'orbit' : 'plain', subtitle:'A NEW STORY BEGINS', description:idea || '每一个故事，都从第一句话开始。', createdAt:new Date().toISOString(), updatedAt:new Date().toISOString(), updated:'刚刚', progress:0, chapters:[{id:uid(), title:kind === '剧本' ? '第一场 · 故事开始' : '第一章 · 故事开始', text}], outline:outline ?? idea, characters };
  setWorks(prev => [work, ...prev]); setModal(null); navigate(`editor/${id}`); notify('新作品已创建，开始你的故事吧');
 };
 const updateWork = work => setWorks(prev => placeRecentlyEdited(prev,work));
 const toggleFavorite = id => { setFavorites(prev => prev.includes(id) ? prev.filter(item => item !== id) : [...prev,id]); };
 const importFile = async event => {try{ const file = event.target.files?.[0]; if (!file) return; if (!/\.txt$/i.test(file.name)) { notify('请导入 TXT 格式的文稿'); return; } const text = await file.text(); if (text.length > 1500000) { notify('请导入小于 150 万字的文稿'); return; } const id = uid(); setWorks(prev => [{ id, title:file.name.replace(/\.txt$/i,''), kind:'长篇小说', genre:'其他', cover:'plain', subtitle:'YOUR OWN STORY', description:'从本地导入的作品', updated:'刚刚', progress:0, chapters:splitManuscript(text), outline:'', characters:'' }, ...prev]); navigate(`editor/${id}`); notify('文稿导入成功'); event.target.value = ''; }catch{notify('文稿读取失败，请检查文件后重试');}finally{event.target.value='';} };
 const openVideo=(work,chapter)=>{setVideoHandoff({workId:work.id,script:chapter?.text||work.chapters.map(c=>c.text).join('\n\n'),title:work.title});navigate('video');};
 const openSubmission=work=>{setSubmissionWorkId(work.id);navigate('submit');};
 const common = { works, navigate, setModal, notify, favorites, openVideo,openSubmission, toggleFavorite, createWork, onImport:() => importRef.current.click(), trashWorks, onRestoreWork:work=>{updateWork({...work,deletedAt:undefined});notify('作品已恢复到书架');} };
 const currentWork = route.startsWith('editor/') && works.find(work => work.id === route.split('/')[1]);
 const currentNav = navItems.find(item => item.id === route) || navItems[0];
 return <>
  {workSaveError&&<div className="storage-error-banner" role="alert"><FileText size={16}/><span>文稿暂未写入本地存储。请先导出作品备份，避免刷新后丢失本次修改。</span>{currentWork&&<button onClick={()=>{downloadText(`${currentWork.title}.txt`,`${currentWork.title}\n\n${currentWork.chapters.map(ch=>`${ch.title}\n\n${ch.text}`).join('\n\n')}`);notify('当前作品已导出');}}>导出当前作品<Download size={14}/></button>}</div>}
  <input type="file" accept=".txt,text/plain" ref={importRef} className="hidden" onChange={importFile}/>
  {currentWork ? <Editor key={currentWork.id} work={currentWork} onChange={updateWork} onBack={() => navigate('works')} notify={notify} setModal={setModal} saveError={workSaveError} openVideo={openVideo} openSubmission={openSubmission}/> : <div className="app-shell refreshed">
   {mobileNav && <button className="mobile-scrim" aria-label="关闭菜单" onClick={() => setMobileNav(false)}/>}
   <aside className={cn('sidebar',mobileNav && 'mobile-open')}>
    <button className="brand" onClick={() => navigate('home')}><Brand/><span>墨多多<span className="brand-writing">写作</span><small>让好故事发生</small></span></button>
    <button className="sidebar-create" onClick={()=>setModal({type:'create'})}><Plus size={17}/>新建作品<span>＋</span></button>
    <nav aria-label="主导航">{navItems.map(item => <React.Fragment key={item.id}>{item.section && <div className="nav-section">{item.section}</div>}<button className={cn('nav-item',item.nested&&'nested',route === item.id && 'active')} aria-current={route===item.id?'page':undefined} onClick={() => navigate(item.id)}><item.icon size={19} strokeWidth={1.75}/><span>{item.label}</span>{item.badge && <small>{item.badge}</small>}{route === item.id && <i/>}</button></React.Fragment>)}</nav>
    <div className="sidebar-bottom"><div className="membership"><div><Crown size={18}/><strong>创作，不止于此</strong></div><p>会员与墨点 · 方案预览</p><button onClick={() => navigate('membership')}>会员与墨点 <ArrowUpRight size={14}/></button></div><button className="help-link" onClick={() => setModal({type:'help'})}><CircleHelp size={17}/>帮助与反馈<ArrowUpRight size={14}/></button><button className="sidebar-user" onClick={() => setModal({type:'account'})}><div className="avatar">墨</div><span><strong>墨多多的创作空间</strong><small><i/>灵感在线</small></span><Settings2 size={16}/></button></div>
   </aside>
   <div className="workspace">
    <header className="topbar"><div className="breadcrumb"><button className="icon-button mobile-menu" aria-label="打开菜单" onClick={() => setMobileNav(true)}><Menu size={21}/></button><span>我的工作台</span><ChevronRight size={13}/><strong>{currentNav.label}</strong></div><div className="topbar-right"><button className="global-search" onClick={() => { setSearch(''); setModal({type:'search'}); }}><Search size={16}/><span>搜索作品、工具或灵感</span><kbd>⌘ K</kbd></button><BillingBadge onClick={()=>navigate('membership')}/><div className="topbar-divider"/><button className="icon-button" aria-label="AI 与数据设置" onClick={()=>setModal({type:'settings'})}><Settings2 size={19}/></button><button className="icon-button notification" aria-label="通知" onClick={() => setModal({type:'notifications'})}><Bell size={19}/><i/></button><button className="avatar small" aria-label="个人空间" onClick={() => setModal({type:'account'})}>墨</button></div></header>
    <main className={cn("main-content",(route==='home'||route==='tools')&&"market-content")} key={`${route}-${workspaceRevision}`}>
     {route === 'home' && <ReferenceHome {...common}/>}
     {route === 'works' && <WorksPage {...common}/> }
     {route === 'novels' && <NovelDesk {...common}/>}
     {route === 'tools' && <ReferenceTools {...common}/>}
     {route === 'workflows' && <WorkflowsPage {...common}/>}
     {route === 'dismantle' && <DismantleDesk {...common}/>}
     {route === 'scripts' && <ScriptsPage {...common}/>}
     {route === 'video' && (videoEnabled?<VideoStudio {...common} initial={videoHandoff}/>:<div className="surface"><Empty title="视频相关功能已暂缓" text="当前版本专注小说、文字剧本与内容编辑，已有资料会保留。" action={<button className="button primary" onClick={()=>navigate('scripts')}>前往文字剧本创作<ArrowRight size={15}/></button>}/></div>)}
     {route === 'submit' && <SubmissionDesk {...common} initialWorkId={submissionWorkId} submissions={submissions} setSubmissions={setSubmissions}/>}
     {route === 'learn' && <LearnPage {...common}/>}
     {route === 'history' && <GenerationHistory {...common} onChange={updateWork}/>}
     {route === 'membership' && <MembershipPage navigate={navigate}/>}
     {!navItems.some(item => item.id === route) && route!=='video' && <ReferenceHome {...common}/>}
     <footer className="page-footer"><span>墨多多写作</span><i/>让灵感落笔，让故事生长。<span className="footer-right"><WorkspaceStatus/><span className="status-dot"/>{workSaveError?'当前有文稿未保存':'文稿自动保存到本机'}</span></footer>
    </main>
   </div>
  </div>}
  {modal && <div className="modal-backdrop" onMouseDown={event => { if(event.target === event.currentTarget) setModal(null); }}><section className={cn('modal',modal.type === 'search' && 'search-modal',modal.type === 'workflow' && 'workflow-modal',modal.type === 'draft-review'&&'draft-review-modal', ['settings','chapters','versions','chapter-plan'].includes(modal.type)&&'wide-modal')} role="dialog" aria-modal="true" aria-label={modal.type === 'create' ? '新建作品' : '墨多多写作'}><button className="modal-close icon-button" aria-label="关闭" onClick={() => setModal(null)}><X size={20}/></button>
   {modal.type === 'settings' && <SettingsDialog works={allWorks} notify={notify} onRestore={data=>{setWorks(data.works);setFavorites(data.favorites);setSubmissions(data.submissions);setWorkspaceRevision(value=>value+1);}}/>}
   {modal.type === 'work-details' && <WorkDetailsDialog work={allWorks.find(w=>w.id===modal.work.id)||modal.work} onSave={work=>{updateWork(work);setModal(null);notify('作品资料已保存');}} onTrash={work=>{updateWork({...work,deletedAt:new Date().toISOString()});setModal(null);if(currentWork)navigate('works');notify('作品已移入回收站，可随时恢复');}}/>}
   {modal.type === 'chapter-plan' && <ChapterPlanner work={allWorks.find(w=>w.id===modal.workId)||currentWork} initialPlans={modal.plans} onChange={updateWork} notify={notify} onClose={()=>setModal(null)}/>}
   {modal.type === 'chapters' && <ChapterManager work={currentWork} chapterId={modal.chapterId} onChange={updateWork} notify={notify}/>}
   {modal.type === 'versions' && <VersionDialog work={currentWork} chapterId={modal.chapterId} onChange={updateWork} notify={notify}/>}
   {modal.type === 'create' && <CreateForm initial={modal} onCreate={createWork}/>}
   {modal.type === 'quick-start' && <QuickStartDialog initial={modal} createWork={createWork}/>}
   {modal.type === 'draft-review' && <DraftReviewDialog before={modal.before} candidate={modal.candidate} task={modal.task} source={modal.source} onApply={modal.onApply}/>}
   {modal.type === 'tool' && <ToolDialog tool={modal.tool} works={works} onFavorite={() => toggleFavorite(modal.tool.id)} favorite={favorites.includes(modal.tool.id)} initial={modal} createWork={createWork} notify={notify} setModal={setModal} onChange={updateWork}/>}
   {modal.type === 'workflow' && <WorkflowDialog flow={modal.flow} works={works} createWork={createWork} initial={modal} onChange={updateWork} setModal={setModal} notify={notify}/>}
   {modal.type === 'search' && <><div className="search-dialog-input"><Search size={22}/><input autoFocus placeholder="查找你的作品、AI 工具和工作流…" value={search} onChange={e => setSearch(e.target.value)}/><kbd>ESC</kbd></div><div className="search-results"><span className="eyebrow">{search ? '搜索结果' : '快速前往'}</span>{works.filter(w => !search || `${w.title}${w.genre}`.includes(search)).map(w => <button key={w.id} onClick={() => {setModal(null); navigate(`editor/${w.id}`);}}><BookOpen size={19}/><span>{w.title}<small>{w.kind} · {w.genre}</small></span><ArrowUpRight size={16}/></button>)}{tools.filter(t => search && `${t.title}${t.desc}`.includes(search)).map(t => <button key={t.id} onClick={() => setModal({type:'tool',tool:t})}><Icon name={t.icon} size={19}/><span>{t.title}<small>AI 工具 · {t.category}</small></span><ArrowUpRight size={16}/></button>)}{workflows.filter(f => search && `${f.title}${f.desc}`.includes(search)).map(f => <button key={f.id} onClick={() => setModal({type:'workflow',flow:f})}><Workflow size={19}/><span>{f.title}<small>创作工作流</small></span><ArrowUpRight size={16}/></button>)}{search && ![...works.map(w=>w.title+w.genre),...tools.map(t=>t.title+t.desc),...workflows.map(f=>f.title+f.desc)].some(t=>t.includes(search)) && <Empty title="还没有找到" text="试试作品名称，或搜索“大纲”“灵感”。"/>}</div></>}
   {modal.type === 'help' && <><div className="modal-symbol"><CircleHelp/></div><h2>让创作顺畅一点</h2><p className="modal-desc">几个小提示，帮你更快进入写作状态。</p><div className="help-items"><div><kbd>⌘ K</kbd><span>快速查找作品与工具</span></div><div><BookOpen size={18}/><span>在「我的作品」新建或导入 TXT 文稿</span></div><div><Download size={18}/><span>编辑器右上角可导出完整作品</span></div><div><CheckCheck size={18}/><span>作品自动保存到本机服务，并保留浏览器缓存，建议定期导出备份</span></div></div><button className="button primary full" onClick={() => setModal(null)}>知道了，继续创作</button></>}
   {modal.type === 'notifications' && <><div className="modal-symbol"><Bell/></div><h2>消息通知</h2><div className="notice-item"><span className="notice-dot"/><div><h4>欢迎来到你的创作空间</h4><p>三部示例作品和精选 AI 工具已准备好。打开一本，试着写下你的第一句话。</p><small>今天</small></div></div><div className="notice-item"><CheckCircle2 size={19}/><div><h4>你的文字会被好好保存</h4><p>当前作品自动保存到本机服务，保留浏览器缓存，随时可以导出 TXT 文稿。</p><small>创作提示</small></div></div></>}
   {modal.type === 'account' && <><div className="profile-avatar">墨</div><h2>墨多多的创作空间</h2><p className="modal-desc">每一天，都离理想中的故事更近一点。</p><div className="profile-stats"><div><strong>{works.length}</strong><span>部作品</span></div><div><strong>{works.reduce((a,w)=>a+workWords(w),0).toLocaleString()}</strong><span>字已落笔</span></div><div><strong>{favorites.length}</strong><span>收藏工具</span></div></div><AccountAccess onClose={()=>setModal(null)}/><AccountBilling onOpen={()=>{setModal(null);billing.go('plans');}}/><div className="soft-notice"><CheckCheck size={17}/>当前使用本地创作空间，内容自动保存在本机服务，并保留浏览器缓存。</div><button className="button secondary full" onClick={()=>setModal({type:'settings'})}><Settings2 size={16}/>AI 与数据设置、整库备份</button><button className="button primary full" onClick={() => {setModal(null);navigate('works');}}>回到我的作品<ArrowRight size={16}/></button></>}
   {modal.type === 'membership' && <><h2>会员与墨点</h2><p className="modal-desc">根据创作频率选择套餐，或按需购买墨点。</p><button className="button primary full" onClick={()=>{setModal(null);billing.go('plans');}}>查看套餐<ArrowRight size={16}/></button></>}
   {modal.type === 'lesson' && <><span className="eyebrow">墨多多 · 写作手记</span><h2>{modal.lesson.title}</h2><p className="modal-desc">{modal.lesson.desc}</p><article className="lesson-content">{modal.lesson.content.split('\n\n').map((p,i)=><p key={i}>{p}</p>)}</article><button className="button primary full" onClick={()=>setModal({type:'create'})}>把方法用在新故事里<Feather size={16}/></button></>}
  </section></div>}
  {toast && <div className="toast" role="status"><CheckCircle2 size={18}/>{toast}</div>}
 </>;
}

function PageHeading({ eyebrow, title, desc, children }) { return <div className="page-heading"><div><h1>{title}</h1>{desc && <p>{desc}</p>}</div><div className="heading-actions">{children}</div></div>; }
function SectionHeading({ title, desc, children }) { return <div className="section-heading"><div><h2>{title}</h2>{desc && <span>{desc}</span>}</div>{children}</div>; }

function ToolCard({ tool, favorite, onFavorite, onOpen }) { return <article className="tool-card"><div className="tool-card-top"><span className={`type-icon ${tool.color}`}><Icon name={tool.icon} size={22} strokeWidth={1.7}/></span><button className={cn('favorite-button',favorite&&'saved')} aria-label={favorite?'取消收藏':'收藏工具'} onClick={onFavorite}><Star size={17} fill={favorite?'currentColor':'none'}/></button></div><button className="tool-card-main" onClick={onOpen}><h3>{tool.title}</h3><p>{tool.desc}</p></button><div className="tool-card-bottom"><span>{tool.tags.map(t=><small key={t}>{t}</small>)}</span><button onClick={onOpen}>使用<ArrowUpRight size={13}/></button></div></article>; }
function WorkflowsPage({ setModal }) { const [filter,setFilter]=useState('全部工作流');return <><PageHeading eyebrow="STEP BY STEP, STORY BY STORY" title="创作工作流" desc="把创作拆成小步骤，让好故事自然而然发生。"/><div className="workflow-intro"><span className="workflow-intro-icon"><Workflow size={30}/></span><div><h3>少一点来回切换，多一点专注创作。</h3><p>串联灵感、大纲、正文与润色。每一步都能查看、修改，由你掌握故事的方向。</p></div><span className="soft-label">你始终是故事的作者</span></div><div className="pill-tabs flow-tabs">{['全部工作流','长篇创作','短篇创作','剧本改编','编辑优化'].map(t=><button className={cn(filter===t&&'active')} key={t} onClick={()=>setFilter(t)}>{t}</button>)}</div><div className="workflow-grid">{workflows.filter(f=>filter==='全部工作流'||f.type===filter).map(flow=><article className="workflow-card" key={flow.id}><div className="workflow-card-head"><span className={`type-icon ${flow.color}`}><Icon name={flow.icon} size={25}/></span><span className="category-tag">{flow.type}</span></div><h2>{flow.title}</h2><p>{flow.desc}</p><div className="flow-nodes">{flow.steps.map((s,i)=><React.Fragment key={s}><span>{s}</span>{i<flow.steps.length-1&&<ChevronRight size={12}/>}</React.Fragment>)}</div><div className="workflow-card-bottom"><span><Workflow size={14}/>{flow.steps.length} 个步骤 · 分步确认</span><button className="button secondary" onClick={()=>setModal({type:'workflow',flow})}>开始工作流<ArrowRight size={15}/></button></div></article>)}</div></>; }

function CreateForm({initial,onCreate}) {
 const [title,setTitle]=useState(initial.title||''); const [kind,setKind]=useState(initial.kind||'长篇小说'); const [genre,setGenre]=useState(initial.genre||'悬疑'); const [idea,setIdea]=useState(initial.idea||'');
 return <form onSubmit={e=>{e.preventDefault();if(title.trim())onCreate({title:title.trim(),kind,genre,idea});}}><div className="modal-symbol"><Feather size={25}/></div><span className="eyebrow">新的创作</span><h2>新建作品</h2><p className="modal-desc">设置名称与题材，创建后即可进入编辑器。</p><label className="field">作品名称<input autoFocus required maxLength={30} value={title} onChange={e=>setTitle(e.target.value)} placeholder="你的下一个好故事，叫什么？"/></label><label className="field">创作类型</label><div className="form-type-options">{['长篇小说','短篇故事','剧本'].map(t=><button type="button" key={t} onClick={()=>setKind(t)} className={cn(kind===t&&'selected')}>{t}{kind===t&&<Check size={14}/>}</button>)}</div><label className="field">题材方向<select value={genre} onChange={e=>setGenre(e.target.value)}>{['悬疑','言情','科幻','奇幻','都市','历史','治愈','其他'].map(t=><option key={t}>{t}</option>)}</select></label><label className="field">最初的灵感<span className="optional">选填</span><textarea value={idea} onChange={e=>setIdea(e.target.value)} placeholder="一个人物、一句话，或者一个你念念不忘的画面…" rows={3}/></label><button type="submit" className="button primary full">创建作品，开始落笔<ArrowRight size={17}/></button><p className="form-footnote">灵感和文字，都会自动保存在这个浏览器。</p></form>;
}

export function ToolDialog({tool,works,onFavorite,favorite,notify,setModal,onChange,initial={},createWork}) {
 const [prompt,setPrompt]=useState('');const [workId,setWorkId]=useState(initial.workId||'');const [selectedChapter,setSelectedChapter]=useState(initial.chapterId||'');const [result,setResult]=useState('');const [busy,setBusy]=useState(false);
 const generation=useGeneration();
 const linked=works.find(w=>w.id===workId);
 const chapter=linked?.chapters.find(c=>c.id===selectedChapter)||linked?.chapters[0];
 const meter=useTaskMeter(tool.id,{inputChars:prompt.length+(linked?.outline?.length||0)+(linked?.characters?.length||0)+(chapter?.text.length||0)});
 const run=()=>meter.run(async()=>{setBusy(true);try{const result=await generation.generate({task:tool.id,prompt,context:linked?{workId:linked.id,chapterId:chapter?.id,title:linked.title,genre:linked.genre,outline:linked.outline,characters:linked.characters,chapterTitle:chapter?.title,chapterPlan:chapter?.plan||'',text:chapter?.text||''}: {},target:meter.outputChars,mode:meter.model},tool.output);setResult(result.text);}finally{setBusy(false);}});
 return <><div className="tool-dialog-heading"><span className={`type-icon ${tool.color}`}><Icon name={tool.icon} size={25}/></span><GenerationStatus generation={generation} busy={busy} onSettings={()=>setModal?.({type:'settings'})}/></div><h2>{tool.title}</h2><p className="modal-desc">{tool.desc}</p><label className="field">关联作品<select aria-label="工具关联作品" disabled={busy} value={workId} onChange={e=>{setWorkId(e.target.value);setResult('');}}><option value="">不关联，先试试灵感</option>{works.map(w=><option key={w.id} value={w.id}>{w.title}</option>)}</select></label>{linked&&<label className="field">引用章节<select aria-label="工具引用章节" disabled={busy} value={chapter?.id||''} onChange={e=>{setSelectedChapter(e.target.value);setResult('');}}>{linked.chapters.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></label>}{workId&&<div className="context-notice"><BookOpen size={15}/>已关联大纲、人物与当前章节正文</div>}<label className="field">你的创作需求<textarea rows={3} value={prompt} onChange={e=>setPrompt(e.target.value)} placeholder="描述你的想法，或粘贴一段想要打磨的文字…"/></label><TaskMeter meter={meter}/><div className="tool-dialog-actions"><button className="button secondary" onClick={onFavorite}><Star size={16} fill={favorite?'currentColor':'none'}/>{favorite?'已收藏':'收藏工具'}</button><button className="button primary" onClick={run} disabled={busy}>{busy?<LoaderCircle className="spin" size={16}/>:<Sparkles size={16}/>} {busy?'灵感正在酝酿…':result?'重新生成':generation.mode==='ai'?'开始生成':'生成示例'}</button></div>{result&&<div className="generated-result"><div><strong>创作参考</strong><button className="text-button" onClick={()=>{copyText(result).then(()=>notify('已复制创作参考')).catch(()=>notify('复制未完成，请手动选择并复制文字'));}}><Copy size={14}/>复制</button></div><textarea aria-label="创作参考，可编辑" value={result} onChange={e=>setResult(e.target.value)} rows={9}/><small>{generation.source==='ai'?'根据你的输入生成，请检查后使用。':'示例内容，可以编辑后使用。'}</small>{linked&&<button className="button secondary full" onClick={()=>{const target=tool.id==='outline'?'outline':tool.id==='character'?'characters':['review','ideas','title'].includes(tool.id)?'notes':'text';const before=target==='text'?chapter.text:linked[target]||'';setModal({type:'draft-review',before,candidate:result,task:tool.title,source:generation.source,onApply:(text,mode)=>{const updated=applyDraft(before,text,mode);onChange(target==='text'?{...saveChapterVersion(linked,chapter,'工具采纳前'),chapters:linked.chapters.map(c=>c.id===chapter.id?{...c,text:updated}:c)}:{...linked,[target]:updated});setModal(null);notify(target==='notes'?'已保存到创作笔记':'创作结果已保存到关联作品');}});}}>预览并保存到关联作品<WandSparkles size={14}/></button>}{!linked&&createWork&&<button className="button secondary full" onClick={()=>createWork({title:tool.title+' · 创作参考',kind:'短篇故事',genre:'其他',text:result,idea:prompt})}>保存为新作品<BookOpen size={15}/></button>}</div>}</>;
}

export function WorkflowDialog({flow,works,createWork,initial={},onChange,setModal,notify}) {
 const [allDrafts,setAllDrafts]=useCollection('workflows',[]);
 const [draft]=useState(()=>allDrafts.find(item=>(item.id===flow.id||item.flowId===flow.id)&&(!initial.workId||item.workId===initial.workId)&&(!initial.chapterId||!item.chapterId||item.chapterId===initial.chapterId)));
 const [draftId,setDraftId]=useState(draft?.id||(initial.workId?`${flow.id}-${initial.workId}${initial.chapterId?'-'+initial.chapterId:''}`:flow.id));
 const savedDrafts=allDrafts.filter(item=>item.id===flow.id||item.flowId===flow.id);
 const [step,setStep]=useState(draft?.step??-1);const [idea,setIdea]=useState(draft?.idea||'');const [title,setTitle]=useState(draft?.title||'');const [content,setContent]=useState(draft?.content||'');const [results,setResults]=useState(draft?.results||{});const [busy,setBusy]=useState(false);const [workId,setWorkId]=useState(initial.workId||draft?.workId||'');const [saveError,setSaveError]=useState(false);
 const [chapterId,setChapterId]=useState(draft?.chapterId||initial.chapterId||'');
 const generation=useGeneration();const sourceWork=works.find(w=>w.id===workId);const sourceChapter=sourceWork?.chapters.find(c=>c.id===chapterId)||sourceWork?.chapters[0];
 useEffect(()=>{const drafts=allDrafts;setSaveError(!setAllDrafts([{id:draftId,flowId:flow.id,step,idea,title,content,results,workId,chapterId,updatedAt:new Date().toISOString()},...drafts.filter(d=>d.id!==draftId)]));},[draftId,step,idea,title,content,results,workId,chapterId]);
 const editContent=value=>{setContent(value);setResults(prev=>Object.fromEntries(Object.entries(prev).filter(([index])=>Number(index)<=step)));};
 const nextLabel=flow.steps[step+1]||'';
 const nextToolId=flow.type==='编辑优化'?(/润色/.test(nextLabel)?'polish':'review'):/人物/.test(nextLabel)?'character':/大纲|规划|结构/.test(nextLabel)?'outline':/润色/.test(nextLabel)?'polish':/检查|建议|分析/.test(nextLabel)?'review':/对白/.test(nextLabel)?'dialogue':step<0?'ideas':'continue';
 const meter=useTaskMeter(nextToolId,{inputChars:idea.length+content.length});
 const run=()=>{const next=step+1;const saved={...results,...(step>=0?{[step]:content}:{})};if(saved[next]!==undefined){setResults(saved);setStep(next);setContent(saved[next]);return;}return meter.run(async()=>{setBusy(true);setResults(saved);try{const result=await generation.generate({task:nextToolId,prompt:idea,stage:nextLabel,previous:Object.fromEntries(Object.entries(saved).map(([index,value])=>[flow.steps[Number(index)],value])),context:{title,workId:sourceWork?.id,chapterId:flow.type==='编辑优化'?sourceChapter?.id:undefined,source:sourceWork?{title:sourceWork.title,outline:sourceWork.outline,characters:sourceWork.characters,text:flow.type==='编辑优化'?sourceChapter?.text||'':sourceWork.chapters.map(c=>c.text).join('\n\n')}:null},target:meter.outputChars,mode:meter.model},tools.find(t=>t.id===nextToolId).output);setStep(next);setContent(result.text);}finally{setBusy(false);}});};
 const writeBack=()=>{if(!sourceWork)return;const chapter=sourceChapter;setModal({type:'draft-review',before:chapter.text,candidate:content,task:flow.title,source:generation.source,onApply:(text,mode)=>{onChange({...saveChapterVersion(sourceWork,chapter,'工作流采纳前'),chapters:sourceWork.chapters.map(c=>c.id===chapter.id?{...c,text:applyDraft(chapter.text,text,mode)}:c)});setAllDrafts(prev=>prev.filter(d=>d.id!==draftId));setModal(null);notify('工作流结果已采纳到原章节');}});};
 const saveFlow=()=>{const saved={...results,[step]:content};const entries=Object.entries(saved).map(([index,text])=>({label:flow.steps[Number(index)],text}));setAllDrafts(prev=>prev.filter(d=>d.id!==draftId));createWork({title:title||'未命名的故事',kind:flow.type==='剧本改编'?'剧本':flow.type==='短篇创作'?'短篇故事':'长篇小说',genre:sourceWork?.genre||'其他',idea:idea||'从创作工作流诞生的新故事',outline:[idea,...entries.filter(e=>!/正文|人物|润色|对白/.test(e.label)).map(e=>`${e.label}\n${e.text}`)].filter(Boolean).join('\n\n'),characters:entries.filter(e=>/人物/.test(e.label)).map(e=>e.text).join('\n\n'),text:entries.filter(e=>/正文|分场剧本|润色|对白/.test(e.label)).map(e=>e.text).at(-1)||''});};
 return <><span className="eyebrow">{flow.type} · 分步创作</span><GenerationStatus generation={generation} busy={busy}/>{saveError&&<p role="alert">草稿未能保存，请复制当前内容备份。</p>}<h2>{flow.title}</h2>{savedDrafts.length>1&&<label className="field">切换已保存草稿<select aria-label="工作流草稿" disabled={busy} value={draftId} onChange={e=>{const d=savedDrafts.find(v=>v.id===e.target.value);setDraftId(d.id);setStep(d.step);setIdea(d.idea);setTitle(d.title);setContent(d.content);setResults(d.results);setWorkId(d.workId||'');setChapterId(d.chapterId||'');}}>{savedDrafts.map(d=><option key={d.id} value={d.id}>{d.title||'未命名的故事'} · {d.id===flow.id?'当前草稿':'恢复的草稿'}</option>)}</select></label>}<p className="modal-desc">每一步都可以修改，故事的方向由你决定。</p><div className="workflow-stepper">{flow.steps.map((s,i)=><div key={s} className={cn(step===i&&'current',step>i&&'done')}><span>{step>i?<Check size={13}/>:i+1}</span><small>{s}</small></div>)}</div>{step<0?<><label className="field">这次故事的名字<input value={title} onChange={e=>setTitle(e.target.value)} placeholder="暂时叫《未命名的故事》"/></label><label className="field">先放进一颗灵感种子<textarea rows={5} value={idea} onChange={e=>{setIdea(e.target.value);setResults({});}} placeholder="比如：一个可以听到旧物记忆的修复师，收到了一件属于未来的物品。"/></label><label className="field">关联原作<select value={workId} onChange={e=>{setWorkId(e.target.value);setChapterId('');setResults({});}}><option value="">不关联作品</option>{works.map(w=><option key={w.id} value={w.id}>{w.title}</option>)}</select></label>{sourceWork&&flow.type==='编辑优化'&&<label className="field">改稿章节<select aria-label="工作流引用章节" value={sourceChapter?.id||''} onChange={e=>{setChapterId(e.target.value);setResults({});}}>{sourceWork.chapters.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></label>}<div className="soft-notice"><Sparkles size={17}/>{generation.mode==='ai'?'每一步会结合原作及此前结果生成。':'示例模式返回预置内容，草稿会自动保留。'}</div></>:<label className="field">第 {step+1} 步 · {flow.steps[step]}<textarea rows={12} value={content} onChange={e=>editContent(e.target.value)}/></label>}{step<flow.steps.length-1&&(results[step+1]!==undefined?<p className="meter-free-note"><CheckCircle2 size={14}/>下一步已有结果，恢复不扣点。</p>:<TaskMeter meter={meter}/>)}<div className="modal-bottom-note"><span>{step>0?<button className="text-button" disabled={busy} onClick={()=>{setResults(prev=>({...prev,[step]:content}));setStep(step-1);setContent(results[step-1]||'');}}><ChevronLeft size={13}/>返回上一步</button>:step===0?<button className="text-button" disabled={busy} onClick={()=>{setResults(prev=>({...prev,[step]:content}));setStep(-1);}}>返回初始设定</button>:'确认这一阶段后，再进入下一步。'}</span>{step===flow.steps.length-1?<span className="workflow-finish-actions">{sourceWork&&flow.type==='编辑优化'&&onChange&&<button className="button secondary" onClick={writeBack}>预览并更新原章节</button>}<button className="button primary" onClick={saveFlow}>保存为新作品<Check size={16}/></button></span>:<button className="button primary" disabled={busy} onClick={run}>{busy?<LoaderCircle className="spin" size={16}/>:<ArrowRight size={16}/>} {busy?'正在准备…':step<0?'开始第一步':'确认并继续'}</button>}</div></>;
}

function ScriptsPage({works,navigate,setModal,favorites,toggleFavorite}) {const scripts=works.filter(w=>w.kind==='剧本');return <><PageHeading eyebrow="WORDS, CAMERA, ACTION" title="剧本创作" desc="从分集大纲到分场对白，写好故事里的每一场戏。"><button className="button primary" onClick={()=>setModal({type:'create',kind:'剧本'})}><Plus size={16}/>新建剧本</button></PageHeading><div className="script-start-grid"><button onClick={()=>setModal({type:'create',kind:'剧本'})}><span className="type-icon purple"><Clapperboard size={30}/></span><h2>从一个画面开始</h2><p>梳理人物行动与对白，写下你心里的第一场戏。</p><span className="text-button">新建空白剧本<ArrowRight size={16}/></span></button><button onClick={()=>setModal({type:'workflow',flow:workflows[2]})}><span className="type-icon green"><Workflow size={30}/></span><h2>让小说换一种表达</h2><p>分析人物、拆分集纲，逐步改编成分场剧本。</p><span className="text-button">体验小说改编<ArrowRight size={16}/></span></button></div><SectionHeading title="我的剧本"/>{scripts.length?<div className="work-grid">{scripts.map(w=><WorkCard key={w.id} work={w} onOpen={()=>navigate(`editor/${w.id}`)}/>)}</div>:<div className="surface"><Empty title="你的第一场戏，即将开场" text="从空白剧本开始，或者让小说改编工作流陪你完成。"/></div>}<SectionHeading title="剧本创作小帮手"/><div className="tool-grid">{tools.filter(t=>['character','dialogue','outline','review'].includes(t.id)).map(t=><ToolCard key={t.id} tool={t} favorite={favorites.includes(t.id)} onOpen={()=>setModal({type:'tool',tool:t})} onFavorite={()=>toggleFavorite(t.id)}/>)}</div></>;}

const lessons=[{title:'第一章，怎样让人读下去？',category:'创作入门',time:'5 分钟',color:'green',desc:'给读者一个具体的人、一个眼前的问题，以及继续往下读的理由。',content:'先让故事发生。与其用很长的篇幅解释世界，不如让主角先面对一个具体问题：门缝里突然出现一封信，末班车驶向一个陌生的站台，老友说了一句不该知道的话。\n\n让读者知道主角想要什么。这个目标不一定宏大，但需要清楚。想回家、想保住一家店、想确认一个消息，都可以成为故事的起点。\n\n给信息留一点空白。一个好开篇并不急着回答所有问题。呈现足够的线索，让读者能够猜测，再用一个小小的意外推动下一页。\n\n现在，试着用三百字写一个场景：主角正在完成一件普通的事，一个意料之外的细节打断了他。'},{title:'比“完美”更重要的人物细节',category:'人物塑造',time:'6 分钟',color:'amber',desc:'从一个小习惯、一处矛盾，找到人物鲜活的入口。',content:'人物首先是一个有欲望的人。他想得到什么？为什么现在必须行动？如果一无所获，他会失去什么？\n\n让性格出现在选择里。不要只告诉读者“她很勇敢”，让她在害怕的时候，仍然伸手推开那扇门。\n\n矛盾让人物有层次。一个严肃的人可能会认真给流浪猫取名字，一个看似自信的人可能反复删除同一句消息。\n\n为角色写一个秘密，再写一个连他自己都不愿承认的愿望。让这两者在故事里慢慢靠近。'},{title:'让 AI 帮忙，保留自己的声音',category:'AI 共创',time:'4 分钟',color:'purple',desc:'把 AI 当成能一起讨论的搭子，让每一次采纳都有你的判断。',content:'先确定你想解决的具体问题。是开篇节奏太慢，还是对白缺少人物特点？越清楚的任务，越容易得到有用的参考。\n\n提供作品上下文。告诉 AI 人物的目标、当前的处境、你不希望改变的设定，并附上一小段你满意的文字作为语气参考。\n\n一次只处理一个层面。先讨论结构，再修改段落，最后打磨词句。这样你能知道每次修改带来了什么变化。\n\n保留自己的选择。对照原稿阅读，留下真正服务于故事的部分。你始终是作品的作者。'}];
function LearnPage({setModal}) {return <><PageHeading eyebrow="GROW A LITTLE, WRITE A LITTLE" title="写作课堂" desc="从开篇、人物到表达，让每一次落笔更有把握。"/><div className="learning-hero"><span className="eyebrow">写作是一场漫长而有趣的练习</span><h2>好故事的背后，<br/>是一次又一次认真落笔。</h2><Feather size={110} strokeWidth={.65}/></div><SectionHeading title="写作手记" desc="不急着成为大师，先享受今天的创作"/><div className="lesson-grid">{lessons.map((l,i)=><button className="lesson-card" key={l.title} onClick={()=>setModal({type:'lesson',lesson:l})}><div className={`lesson-cover ${l.color}`}><span>写作手记</span><strong>0{i+1}</strong><Feather size={48} strokeWidth={1}/></div><div><span className="eyebrow">{l.category} · {l.time}</span><h3>{l.title}</h3><p>{l.desc}</p><span className="text-button">读一读<ArrowRight size={15}/></span></div></button>)}</div></>;}

async function copyText(text) { if (!navigator.clipboard) throw new Error('Clipboard unavailable');await navigator.clipboard.writeText(text); }
function downloadText(name,text) {const blob=new Blob(['\ufeff'+text],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

export function Editor({work,onChange,onBack,notify,setModal,saveError=false,openVideo,openSubmission}) {
 const [chapterId,setChapterId]=useState(work.chapters[0]?.id);const [tab,setTab]=useState('正文');const [aiTab,setAiTab]=useState('AI 助手');const [prompt,setPrompt]=useState('');const [answer,setAnswer]=useState('');const [busy,setBusy]=useState(false);const [focus,setFocus]=useState(false);const [showAI,setShowAI]=useState(() => typeof window === 'undefined' || window.innerWidth > 1180);const [fontSize,setFontSize]=useState(17);const [saveState,setSaveState]=useState('已自动保存');const [aiAction,setAiAction]=useState('续写故事');const [customChapter,setCustomChapter]=useState(false);const [chapterName,setChapterName]=useState('');const [showChapters,setShowChapters]=useState(false);const manuscriptRef=useRef();const [lastAdoption,setLastAdoption]=useState(null);
 const generation=useGeneration();const workspace=useWorkspace();
 const displayedSave=workspace?(workspace.status==='saved'?'已保存到本机':workspace.status==='offline'?'离线缓存中':'保存中…'):saveState;
 useEffect(()=>{setAnswer('');generation.cancel();},[chapterId,tab,aiAction]);
 const chapter=work.chapters.find(ch=>ch.id===chapterId)||work.chapters[0];
 useEffect(()=>{if(!work.chapters.some(ch=>ch.id===chapterId))setChapterId(work.chapters[0].id);},[work.chapters,chapterId]);
 useEffect(()=>{const field=manuscriptRef.current;if(field){field.style.height='auto';field.style.height=`${Math.max(550,field.scrollHeight)}px`;}},[chapter?.text,work.outline,work.characters,tab,chapterId,fontSize,showAI,focus]);
 const field=tab==='大纲'?'outline':tab==='人物'?'characters':'notes';
 const save=value=>{setLastAdoption(null);setSaveState('保存中…');if(tab==='正文'){onChange({...work,chapters:work.chapters.map(ch=>ch.id===chapter.id?{...ch,text:value}:ch)});}else onChange({...work,[field]:value});setTimeout(()=>setSaveState('已自动保存'),400);};
 const addChapter=()=>{const id=uid();onChange({...work,chapters:[...work.chapters,{id,title:chapterName.trim()||`第${work.chapters.length+1}章 · 未命名章节`,text:''}]});setChapterId(id);setTab('正文');setChapterName('');setCustomChapter(false);setShowChapters(false);notify('新章节已创建');};
 const taskId=aiAction==='润色文字'?'polish':aiAction==='检查逻辑'?'review':aiAction==='灵感脑洞'?'ideas':'continue';
 const meter=useTaskMeter(taskId,{inputChars:prompt.length+(work.outline?.length||0)+(work.characters?.length||0)+(tab==='正文'?chapter.text.length:tab==='大纲'?(work.outline?.length||0):(work.characters?.length||0))});
 const generate=()=>meter.run(async()=>{setBusy(true);try{const result=await generation.generate({task:taskId,prompt,context:{workId:work.id,chapterId:chapter.id,title:work.title,genre:work.genre,outline:work.outline,characters:work.characters,chapterPlan:chapter.plan||'',previousChapter:work.chapters[Math.max(0,work.chapters.indexOf(chapter)-1)]?.text?.slice(-3000)||'',chapterTitle:chapter.title,text:tab==='正文'?chapter.text:(work[field]||'')},target:meter.outputChars,mode:meter.model},tools.find(t=>t.id===taskId).output);setAnswer(result.text);}finally{setBusy(false);}});
 const reviewCandidate=()=>{if(taskId==='review'){setModal({type:'draft-review',before:work.notes||'',candidate:answer,task:'审稿建议 · 保存到笔记',source:generation.source,onApply:(candidate,mode)=>{onChange({...work,notes:applyDraft(work.notes||'',candidate,mode)});setModal(null);notify('审稿建议已保存到创作笔记，正文保持原样');}});return;}const before=tab==='正文'?chapter.text:(work[field]||'');setModal({type:'draft-review',before,candidate:answer,task:aiAction,source:generation.source,onApply:(candidate,mode)=>{const next=applyDraft(before,candidate,mode);if(tab==='正文'){onChange({...saveChapterVersion(work,chapter,'AI 采纳前'),chapters:work.chapters.map(c=>c.id===chapter.id?{...c,text:next}:c)});}else save(next);setLastAdoption({tab,chapterId:chapter.id,text:before});setModal(null);notify('已采纳到文稿，可撤销本次修改');}});};
 const undoAdoption=()=>{if(!lastAdoption)return;const previous=lastAdoption;if(previous.tab==='正文'){onChange({...work,chapters:work.chapters.map(ch=>ch.id===previous.chapterId?{...ch,text:previous.text}:ch)});}else{onChange({...work,[previous.tab==='大纲'?'outline':previous.tab==='人物'?'characters':'notes']:previous.text});}setLastAdoption(null);notify('已恢复采纳前的文稿');};
 const exportWork=()=>{downloadText(`${work.title}.txt`,`${work.title}\n\n${work.chapters.map(ch=>`${ch.title}\n\n${ch.text}`).join('\n\n')}`);notify('完整作品已导出为 TXT');};
 return <div className={cn('editor-app',focus&&'focus-mode')}><header className="editor-header"><div><button className="icon-button" aria-label="返回作品" onClick={onBack}><ArrowLeft size={20}/></button><button className="icon-button editor-mobile-chapters" aria-label="打开章节目录" onClick={()=>{setShowChapters(!showChapters);if(window.innerWidth<=1000)setShowAI(false);}}><Menu size={19}/></button><span className="editor-header-divider"/><Brand small/><button className="editor-book-name" onClick={()=>setModal({type:'work-details',work})}>{work.title}</button><span className="category-tag">{work.kind}</span></div><div><WorkspaceStatus/><button className="icon-button" aria-label="生成章节规划" title="生成章节规划" onClick={()=>setModal({type:'chapter-plan',workId:work.id})}><ListTree size={17}/></button>{videoEnabled&&openVideo&&<button className="icon-button" aria-label="当前章节转分镜" title="当前章节转分镜" onClick={()=>openVideo(work,chapter)}><Clapperboard size={17}/></button>}{openSubmission&&<button className="icon-button" aria-label="准备投稿" title="准备投稿" onClick={()=>openSubmission(work)}><Send size={17}/></button>}<span className="save-indicator"><CheckCheck size={14}/>{saveError?'缓存保存未完成':displayedSave}</span><button className="icon-button" aria-label="章节版本记录" title="章节版本记录" onClick={()=>setModal({type:'versions',chapterId:chapter.id})}><Clock3 size={17}/></button><button className="icon-button" aria-label="AI 与数据设置" onClick={()=>setModal({type:'settings'})}><Settings2 size={17}/></button>{lastAdoption&&<button className="undo-adoption" onClick={undoAdoption}><RefreshCw size={13}/>撤销采纳</button>}<button className="icon-button" aria-label={focus?'退出专注模式':'专注模式'} onClick={()=>setFocus(!focus)}><Maximize2 size={17}/></button><button className="button secondary small-button" aria-label="导出作品" title="导出作品" onClick={exportWork}><Download size={15}/>导出作品</button><button className="button primary small-button" aria-pressed={showAI} onClick={()=>{setShowAI(!showAI);setShowChapters(false);setFocus(false);}}><Sparkles size={15}/>AI 助手</button></div></header>
  <div className="editor-body">{showAI&&<button className="ai-scrim" aria-label="关闭 AI 助手" onClick={()=>setShowAI(false)}/>} {showChapters&&<button className="chapter-scrim" aria-label="关闭章节目录" onClick={()=>setShowChapters(false)}/>}<aside className={cn("chapter-sidebar",showChapters&&"chapter-open")}><div className="chapter-book"><BookCover work={work}/><h3>{work.title}</h3><span>{workWords(work).toLocaleString()} 字 · {work.chapters.length} 章</span></div><div className="editor-nav-tabs">{['正文','大纲','人物','笔记'].map(t=><button key={t} className={cn(tab===t&&'active')} onClick={()=>{setTab(t);setShowChapters(false);}}>{t}</button>)}</div><div className="chapter-list-heading"><span>{tab==='正文'?'章节目录':tab==='大纲'?'故事规划':'人物资料'}</span>{tab==='正文'&&<button className="icon-button" aria-label="管理章节" title="管理章节" onClick={()=>setModal({type:'chapters',chapterId:chapter.id})}><Settings2 size={16}/></button>}{tab==='正文'&&<button className="icon-button" aria-label="添加章节" onClick={()=>setCustomChapter(true)}><Plus size={17}/></button>}</div>{tab==='正文'?<div className="chapter-list">{work.chapters.map((ch,i)=><button key={ch.id} onClick={()=>{setChapterId(ch.id);setShowChapters(false);}} className={cn(chapter.id===ch.id&&'active')}><FileText size={15}/><span>{ch.title}<small>{wordCount(ch.text)} 字</small></span></button>)}{customChapter?<form className="new-chapter-form" onSubmit={e=>{e.preventDefault();addChapter();}}><input autoFocus aria-label="新章节名称" placeholder="新章节名称" value={chapterName} onChange={e=>setChapterName(e.target.value)}/><div><button type="button" onClick={()=>setCustomChapter(false)}>取消</button><button type="submit">添加</button></div></form>:<button className="add-chapter" onClick={()=>setCustomChapter(true)}><Plus size={15}/>新建章节</button>}</div>:<div className="chapter-list"><button className="active"><ListTree size={15}/><span>{tab==='大纲'?'作品总纲':tab==='人物'?'角色设定':'审稿与创作笔记'}<small>随时补充与修改</small></span></button></div>}<div className="chapter-side-bottom"><span className="status-dot"/>你的文字，正在生长</div></aside>
   <section className="writing-area"><div className="editor-toolbar"><div className="editor-path"><span>{work.title}</span><ChevronRight size={12}/><strong>{tab==='正文'?'正文':tab==='大纲'?'作品大纲':tab==='人物'?'人物设定':'创作笔记'}</strong></div><div><button className="icon-button" aria-label="减小字号" onClick={()=>setFontSize(Math.max(14,fontSize-1))}><span className="font-control">A−</span></button><span className="font-size">{fontSize}</span><button className="icon-button" aria-label="增大字号" onClick={()=>setFontSize(Math.min(25,fontSize+1))}><span className="font-control">A+</span></button><span className="editor-header-divider"/><button className="icon-button" aria-label="显示或隐藏 AI 面板" aria-pressed={showAI} onClick={()=>{setShowAI(!showAI);setShowChapters(false);setFocus(false);}}><PanelRightClose size={17}/></button></div></div><div className="manuscript"><div className="manuscript-inner">{tab==='正文'?<input className="chapter-title-input" aria-label="章节标题" value={chapter.title} onChange={e=>onChange({...work,chapters:work.chapters.map(ch=>ch.id===chapter.id?{...ch,title:e.target.value}:ch)})}/>:<h1>{tab==='大纲'?'故事的骨架':tab==='人物'?'让人物活起来':'创作笔记'}</h1>}{tab==='正文'&&chapter.plan&&<details className="chapter-plan-note"><summary>本章创作规划</summary><p>{chapter.plan}</p></details>}<div className="chapter-writing-meta"><span>{tab==='正文'?`${wordCount(chapter.text)} 字`:'每一个设定，都是故事的一部分'}</span><span>浏览器缓存 · 本机持久保存</span></div><textarea ref={manuscriptRef} className="manuscript-text" aria-label={tab==='正文'?'章节正文':tab==='大纲'?'作品大纲':tab==='人物'?'人物设定':'创作笔记'} style={{fontSize:`${fontSize}px`}} value={tab==='正文'?chapter.text:(work[field]||'')} onChange={e=>save(e.target.value)} placeholder={tab==='正文'?'故事，就从这一行开始。\n\n写下你脑海里的第一个画面…':tab==='大纲'?'记录主线、关键转折和每一卷的目标。':tab==='人物'?'给人物一个名字，再给他一个不得不行动的理由。':'记录审稿建议、修改计划、伏笔与创作想法。'}/><div className="manuscript-end"><span/>未完，待续<span/></div></div></div><footer className={cn("editor-status",saveError&&"save-error")}><span><span className="status-dot"/>{saveError?'本地保存失败，请导出备份':'本地自动保存'}</span><span>本章 {wordCount(chapter.text)} 字 <i/>全书 {workWords(work)} 字</span><button onClick={()=>setFocus(!focus)}>{focus?'退出专注':'进入专注'}<Maximize2 size={12}/></button></footer></section>
   {showAI&&<aside className="ai-panel"><div className="ai-panel-tabs">{['AI 助手','工具箱','工作流'].map(t=><button key={t} onClick={()=>setAiTab(t)} className={cn(aiTab===t&&'active')}>{t}</button>)}</div>{aiTab==='AI 助手'?<><div className="ai-welcome"><div className="ai-avatar"><Sparkles size={22}/></div><h3>故事卡住了？一起想想。</h3><p>我在这里，陪你找回落笔的灵感。</p><GenerationStatus generation={generation} busy={busy} onSettings={()=>setModal({type:'settings'})}/></div><div className="ai-context"><span><BookOpen size={14}/>当前创作上下文</span><div><small><Check size={12}/>作品大纲</small><small><Check size={12}/>人物设定</small><small><Check size={12}/>当前章节</small></div></div><div className="ai-actions">{[{name:'续写故事',icon:Feather},{name:'润色文字',icon:WandSparkles},{name:'检查逻辑',icon:ScanText},{name:'灵感脑洞',icon:Lightbulb}].map(a=><button key={a.name} className={cn(aiAction===a.name&&'active')} onClick={()=>setAiAction(a.name)}><a.icon size={16}/>{a.name}</button>)}</div><div className="ai-answer-area">{busy?<div className="ai-thinking"><LoaderCircle className="spin" size={18}/>正在酝酿一个好想法…</div>:answer?<div className="ai-answer"><div><Sparkles size={14}/>创作参考</div><p>{answer}</p><div className="answer-actions"><button onClick={()=>{copyText(answer).then(()=>notify('已复制候选文字')).catch(()=>notify('复制未完成，请手动选择并复制文字'));}}><Copy size={14}/>复制</button><button onClick={reviewCandidate}><WandSparkles size={14}/>预览并采纳</button></div><small>{generation.source==='ai'?'AI 生成内容，请核对后采纳。':'示例内容，可编辑后使用。'}</small></div>:<div className="ai-idle"><span>✧</span><p>选择一个任务，写下你的要求。<br/>先预览，再决定是否采纳。</p></div>}</div><TaskMeter meter={meter} compact/><div className="ai-prompt-box"><textarea aria-label="给 AI 的创作要求" placeholder="说说你的想法，或选择上方的创作任务…" rows={3} value={prompt} onChange={e=>setPrompt(e.target.value)}/><div><span>{aiAction} · {generation.mode==='ai'?'真实 AI':'示例模式'}</span><button aria-label={generation.mode==='ai'?'生成创作内容':'生成创作示例'} onClick={generate} disabled={busy}>{busy?<LoaderCircle className="spin" size={15}/>:<ArrowRight size={17}/>}</button></div></div><span className="ai-disclaimer">灵感由 AI 辅助，故事由你决定。</span></>:<div className="editor-tool-list">{aiTab==='工具箱'?tools.map(t=><button key={t.id} onClick={()=>setModal({type:'tool',tool:t,workId:work.id,chapterId:chapter.id})}><span className={`type-icon ${t.color}`}><Icon name={t.icon} size={19}/></span><span><strong>{t.title}</strong><small>{t.category}</small></span><ChevronRight size={14}/></button>):workflows.map(f=><button key={f.id} onClick={()=>setModal({type:'workflow',flow:f,workId:work.id,chapterId:chapter.id})}><span className={`type-icon ${f.color}`}><Workflow size={19}/></span><span><strong>{f.title}</strong><small>{f.steps.length} 个步骤</small></span><ChevronRight size={14}/></button>)}</div>}</aside>}
  </div>
 </div>;
}
